<script setup lang="ts">
import {ref,onMounted} from 'vue'
const emit=defineEmits<{created:[id:string]}>()
const selectedCities=ref(['Lagos']),selectedCategories=ref(['bags','stationery','baby_goods']),limit=ref(20),enrich=ref(false),busy=ref(false),message=ref(''),error=ref(''),daily=ref(12),lastTask=ref<{status:string;message:string}|null>(null)
const cityOptions={Lagos:'拉各斯',Abuja:'阿布贾',Ibadan:'伊巴丹'},categoryOptions={bags:'箱包店',stationery:'文具店',baby_goods:'母婴用品店',toys:'玩具店',clothes:'服装店（相关性待核实）'}
onMounted(async()=>{try{const r=await fetch('/api/maps/capabilities');if(r.ok){const d=await r.json();daily.value=d.dailyRequestLimit;lastTask.value=d.lastTask}}catch{}})
async function start(){busy.value=true;message.value='';error.value='';try{const r=await fetch('/api/maps/tasks',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({cities:selectedCities.value,categories:selectedCategories.value,limit:limit.value,enrichWebsite:enrich.value})});const d=await r.json();if(!r.ok)throw Error(d.error||'地图任务创建失败');message.value='任务已排队；结果会出现在下方任务记录，失败会显示原因。';emit('created',d.id)}catch(e){error.value=e instanceof Error?e.message:'连接失败'}finally{busy.value=false}}
</script>
<template><section class="panel maps-panel"><div class="section-title"><div><span class="tag">地图商家发现 · OpenStreetMap</span><h2>先找到店铺，再核实书包与三件套需求</h2></div><span class="tag">非 Google Maps 数据</span></div><p>使用开放地图登记资料，无需 Google 密钥。公共接口可能限流或超时，尼日利亚店铺覆盖和联系方式可能不完整；不承诺找到指定数量。</p><p v-if="lastTask?.status==='failed'" class="maps-error" role="status">最近实网任务未成功：{{lastTask.message}}。执行器已开发，但公共服务可用性尚未验收。</p><div class="map-form-grid"><div><h2>城市范围</h2><label v-for="(label,key) in cityOptions"><input v-model="selectedCities" type="checkbox" :value="key"/> {{label}} · {{key}}</label></div><div><h2>店铺类型</h2><label v-for="(label,key) in categoryOptions"><input v-model="selectedCategories" type="checkbox" :value="key"/> {{label}}</label></div><div><label>候选店铺上限<input v-model.number="limit" type="number" min="1" max="50"/></label><label><input v-model="enrich" type="checkbox"/> 尝试从公开官网补全邮箱</label><p>仅访问公开官网并检查 robots.txt；受阻则保留原线索。地图和官网信息都需人工核对。</p></div></div><div class="maps-action"><button class="primary" :disabled="busy||!selectedCities.length||!selectedCategories.length" @click="start">{{busy?'正在创建…':'开始地图商家检索'}}</button><span>每任务最多 {{selectedCities.length}} 次地图请求；当前全局限额 {{daily}} 次 / UTC 日。无自动收费重试。</span></div><p v-if="message" role="status">{{message}}</p><p v-if="error" role="alert" class="maps-error">{{error}}</p><div class="maps-attribution">数据来源：<a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener noreferrer">© OpenStreetMap contributors · ODbL</a>。Google Maps 仍保留为后续方向，未将其数据批量复制进客户库。</div></section></template>
<style scoped>.maps-panel{margin:22px 0;background:linear-gradient(130deg,#f2f8f5,#fff)}.maps-panel h2{margin-top:14px}.map-form-grid{display:grid;grid-template-columns:1fr 1.2fr 1.3fr;gap:24px;margin:20px 0}.map-form-grid label{margin:12px 0}.map-form-grid input[type=checkbox]{display:inline;width:auto;margin:0 6px 0 0}.map-form-grid input[type=number]{max-width:150px}.maps-action{display:flex;align-items:center;gap:20px}.maps-action span,.maps-attribution{font-size:10px;line-height:1.9;color:#718579}.maps-attribution{border-top:1px solid #e0e8e2;margin-top:20px;padding-top:15px}a{color:#357e73}.maps-error{color:#963b56}@media(max-width:900px){.map-form-grid{grid-template-columns:1fr}.maps-action{align-items:flex-start;flex-direction:column}}
</style>
